def main() -> int:
    OUT.mkdir(parents=True, exist_ok=True)
    n = 0
    for d in DEFS:
        rec = {"document_id": d["document_id"], "title": d["title"], "mode": "block-for-existing-order",
               "section_id": "key-facts", "section_title": "עיקרי הפקודה", "source_pdf": d["source_pdf"],
               "pages_read": d["pages_read"], "published": d["published"], "draft_note": NOTE,
               "ingest_note": "קליטה: INGEST_SHORT_ORDERS=1 (שכבת-הטקסט תקינה — OCR ≈ שכבה, night/ocr.py 23.09); הבלוק מוחל אחרי הקליטה",
               "roles": d["roles"], "clauses": d["clauses"], "anchor_questions": d["anchor_questions"],
               "review": d["review"]}
        (OUT / f"{d['document_id']}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1) + "\n", encoding="utf-8", newline="\n")
        n += 1
    for d in FOI_DEFS:
        rec = {**d, "mode": "new-document-from-text", "section_id": "key-facts", "section_title": "עיקרי ההוראה", "draft_note": NOTE,
               "ingest_note": "קליטה מטקסט (OCR או שכבת-טקסט) של keep_pages בלבד — מנגנון ingest-from-text נדרש (ראה README); הבלוק מוחל אחרי הקליטה"}
        (OUT / f"{d['document_id']}.json").write_text(json.dumps(rec, ensure_ascii=False, indent=1) + "\n", encoding="utf-8", newline="\n")
        n += 1
    print(f"[wave8] {n} definitions -> {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
